* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
.hm-wrap {
  height: calc(var(--appsmith-ui-height) * 1px);
  width: calc(var(--appsmith-ui-width) * 1px);
  overflow: auto;
  background: #1E293B;
  border: 1px solid #334155;
  border-radius: 6px;
  font-family: system-ui;
}
table.hm { border-collapse: collapse; width: max-content; min-width: 100%; background: #1E293B; }
table.hm th { padding: 8px 10px; font-size: 12px; font-weight: 700; color: #F1F5F9; white-space: nowrap; text-align: left; border-bottom: 2px solid #475569; background: #334155; }
table.hm th.mon { padding: 8px 6px; text-align: center; border-left: 1px solid #475569; }
table.hm td { padding: 6px 10px; font-size: 12px; color: #E2E8F0; white-space: nowrap; border-bottom: 1px solid #334155; }
table.hm td.pct { text-align: right; }
table.hm td.vendor { min-width: 170px; }
table.hm td.sp { width: 42px; }
table.hm td.cell { width: 42px; padding: 0; border-bottom: 1px solid #1E293B; border-left: 1px solid #1E293B; }
table.hm td.cov { background: #15803d; }
table.hm td.unc { background: #E76D5F; }
.empty { padding: 20px; color: #94A3B8; text-align: center; font-family: system-ui; }

srcDoc.js:
function monthLabel(ym) {
  var m = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  return m[parseInt(ym.slice(5,7),10)-1] || ym;
}
function esc(s) {
  return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function render(model) {
  var root = document.getElementById('root');
  if (!root) return;
  var rows = (model && model.rows) || [];
  var axis = (model && model.axis) || [];
  var showVendor = !!(model && model.showVendor);
  if (!rows.length || !axis.length) {
    root.innerHTML = '<div class="empty">No data available</div>';
    return;
  }
  var groups = [];
  axis.forEach(function(ym){
    var y = ym.slice(0,4);
    var last = groups[groups.length-1];
    if (last && last.year === y) last.months.push(ym);
    else groups.push({ year: y, months: [ym] });
  });
  var fixed = ['Location','Account','Meter','Utility','Bill Type','%Last12Mo'];
  var h = '<table class="hm"><thead>';
  h += '<tr><th colspan="' + fixed.length + '"></th><th class="mon">Service Year</th>';
  groups.forEach(function(g){ h += '<th class="mon" colspan="' + g.months.length + '">' + g.year + '</th>'; });
  h += '</tr><tr>';
  fixed.forEach(function(c){ h += '<th>' + c + '</th>'; });
  h += '<th class="mon"' + (showVendor ? ' style="text-align:left;min-width:170px;"' : '') + '>' + (showVendor ? 'Vendor' : '') + '</th>';
  axis.forEach(function(ym){ h += '<th class="mon">' + monthLabel(ym) + '</th>'; });
  h += '</tr></thead><tbody>';
  rows.forEach(function(r){
    var months = r.months || {};
    var pct = (typeof r.pct === 'number') ? r.pct : 0;
    h += '<tr>';
    h += '<td>' + esc(r.location) + '</td><td>' + esc(r.account) + '</td><td>' + esc(r.meter) + '</td><td>' + esc(r.utility) + '</td><td>' + esc(r.billType) + '</td>';
    h += '<td class="pct">' + pct.toFixed(2) + '%</td>';
    h += showVendor ? ('<td class="vendor">' + esc(r.vendor) + '</td>') : '<td class="sp"></td>';
    axis.forEach(function(ym){ h += '<td class="cell ' + (months[ym] ? 'cov' : 'unc') + '"></td>'; });
    h += '</tr>';
  });
  h += '</tbody></table>';
  root.innerHTML = h;
}
appsmith.onReady(function(){
  render(appsmith.model);
  appsmith.onModelChange(function(m){ render(m); });
});

